[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "flight-options-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "flight-options-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "assumptions_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "assumptions_col",
                    "type": "Column",
                    "properties": {
                      "children": [
                        {
                          "id": "assumptions_title",
                          "type": "Text",
                          "properties": {
                            "text": "Assumptions",
                            "style": "title"
                          }
                        },
                        {
                          "id": "assumptions_text",
                          "type": "Text",
                          "properties": {
                            "text": "- Direct flight duration from London (LHR) to New York (JFK) is approximately 7 hours 45 minutes.\n- Flight duration from London (LHR) to Paris (CDG) is approximately 1 hour 15 minutes.\n- Flight duration from Paris (CDG) to New York (JFK) is approximately 8 hours 0 minutes.\n- All flights are for 2024-11-10."
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "options_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "options_col",
                    "type": "Column",
                    "properties": {
                      "children": [
                        {
                          "id": "options_title",
                          "type": "Text",
                          "properties": {
                            "text": "Flight Options from London (LHR) to New York (JFK)",
                            "style": "title"
                          }
                        },
                        {
                          "id": "flight_table",
                          "type": "Table",
                          "properties": {
                            "columns": [
                              {
                                "header": "Option"
                              },
                              {
                                "header": "Airline"
                              },
                              {
                                "header": "Price"
                              },
                              {
                                "header": "Departure"
                              },
                              {
                                "header": "Stops"
                              },
                              {
                                "header": "Layover"
                              },
                              {
                                "header": "Travel Duration"
                              }
                            ],
                            "rows": [
                              {
                                "cells": [
                                  {
                                    "text": "A"
                                  },
                                  {
                                    "text": "British Airways"
                                  },
                                  {
                                    "text": "$650"
                                  },
                                  {
                                    "text": "08:30"
                                  },
                                  {
                                    "text": "Direct"
                                  },
                                  {
                                    "text": "N/A"
                                  },
                                  {
                                    "text": "~7h 45m"
                                  }
                                ]
                              },
                              {
                                "cells": [
                                  {
                                    "text": "B"
                                  },
                                  {
                                    "text": "Virgin Atlantic"
                                  },
                                  {
                                    "text": "$720"
                                  },
                                  {
                                    "text": "11:00"
                                  },
                                  {
                                    "text": "Direct"
                                  },
                                  {
                                    "text": "N/A"
                                  },
                                  {
                                    "text": "~7h 45m"
                                  }
                                ]
                              },
                              {
                                "cells": [
                                  {
                                    "text": "C"
                                  },
                                  {
                                    "text": "Air France"
                                  },
                                  {
                                    "text": "$510"
                                  },
                                  {
                                    "text": "07:00"
                                  },
                                  {
                                    "text": "1 stop (CDG)"
                                  },
                                  {
                                    "text": "2h"
                                  },
                                  {
                                    "text": "~11h 15m"
                                  }
                                ]
                              }
                            ]
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "rankings_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "rankings_tabs",
                    "type": "Tabs",
                    "properties": {
                      "tabs": [
                        {
                          "label": "By Price",
                          "childId": "price_ranking_list"
                        },
                        {
                          "label": "By Duration",
                          "childId": "duration_ranking_list"
                        }
                      ],
                      "children": [
                        {
                          "id": "price_ranking_list",
                          "type": "List",
                          "properties": {
                            "children": [
                              {
                                "id": "price_rank_1",
                                "type": "ListItem",
                                "properties": {
                                  "primaryText": "1. Option C (Air France): $510"
                                }
                              },
                              {
                                "id": "price_rank_2",
                                "type": "ListItem",
                                "properties": {
                                  "primaryText": "2. Option A (British Airways): $650"
                                }
                              },
                              {
                                "id": "price_rank_3",
                                "type": "ListItem",
                                "properties": {
                                  "primaryText": "3. Option B (Virgin Atlantic): $720"
                                }
                              }
                            ]
                          }
                        },
                        {
                          "id": "duration_ranking_list",
                          "type": "List",
                          "properties": {
                            "children": [
                              {
                                "id": "duration_rank_1",
                                "type": "ListItem",
                                "properties": {
                                  "primaryText": "1. Option A (British Airways): ~7h 45m"
                                }
                              },
                              {
                                "id": "duration_rank_2",
                                "type": "ListItem",
                                "properties": {
                                  "primaryText": "2. Option B (Virgin Atlantic): ~7h 45m"
                                }
                              },
                              {
                                "id": "duration_rank_3",
                                "type": "ListItem",
                                "properties": {
                                  "primaryText": "3. Option C (Air France): ~11h 15m"
                                }
                              }
                            ]
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "actions_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "actions_col",
                    "type": "Column",
                    "properties": {
                      "children": [
                        {
                          "id": "actions_title",
                          "type": "Text",
                          "properties": {
                            "text": "Quick Actions",
                            "style": "title"
                          }
                        },
                        {
                          "id": "actions_row",
                          "type": "Row",
                          "properties": {
                            "children": [
                              {
                                "id": "ba_button",
                                "type": "Button",
                                "properties": {
                                  "label": "British Airways",
                                  "action": {
                                    "functionCall": {
                                      "call": "openUrl",
                                      "args": {
                                        "url": "https://www.britishairways.com/flights"
                                      }
                                    }
                                  }
                                }
                              },
                              {
                                "id": "va_button",
                                "type": "Button",
                                "properties": {
                                  "label": "Virgin Atlantic",
                                  "action": {
                                    "functionCall": {
                                      "call": "openUrl",
                                      "args": {
                                        "url": "https://www.virginatlantic.com/flights"
                                      }
                                    }
                                  }
                                }
                              },
                              {
                                "id": "af_button",
                                "type": "Button",
                                "properties": {
                                  "label": "Air France",
                                  "action": {
                                    "functionCall": {
                                      "call": "openUrl",
                                      "args": {
                                        "url": "https://www.airfrance.com/flights"
                                      }
                                    }
                                  }
                                }
                              }
                            ]
                          }
                        }
                      ]
                    }
                  }
                }
              }
            ]
          }
        }
      ]
    }
  }
]
